function matrixScore(grid) {
  // Try every set of flips along the shorter side; each line on the other side then picks its better state alone.
  const m = grid.length, n = grid[0].length;
  const cell = m <= n ? (fixed, other, mask) => grid[fixed][other] ^ ((mask >> fixed) & 1) : (fixed, other, mask) => grid[other][fixed] ^ ((mask >> fixed) & 1);
  let best = 0;
  if (m <= n) {
    for (let mask = 0; mask < 1 << m; mask++) {
      let total = 0;
      for (let c = 0; c < n; c++) {
        let ones = 0;
        for (let r = 0; r < m; r++) ones += cell(r, c, mask);
        total += Math.max(ones, m - ones) * 2 ** (n - 1 - c);
      }
      best = Math.max(best, total);
    }
  } else {
    for (let mask = 0; mask < 1 << n; mask++) {
      let total = 0;
      for (let r = 0; r < m; r++) {
        let value = 0, flipped = 0;
        for (let c = 0; c < n; c++) { const bit = cell(c, r, mask); value = value * 2 + bit; flipped = flipped * 2 + (1 - bit); }
        total += Math.max(value, flipped);
      }
      best = Math.max(best, total);
    }
  }
  return best;
}

