function generate(rand, size) {
  const m = size === 'large' ? 20 : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 20 : 1 + Math.floor(rand() * 5);
  const density = [0, 1, 0.5, rand()][Math.floor(rand() * 4)];
